     1	/**
     2	 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
     3	 *
     4	 * Must call (do not reimplement): getPlanLimits, isArchived
     5	 */
     6	import { getPlanLimits } from "@/config/plan-limits";
     7	import { createLogger } from "@/lib/logger";
     8	import { isArchived } from "@/lib/soft-delete";
     9	import * as activityRepo from "@/server/repositories/activity-repository";
    10	import * as issueRepo from "@/server/repositories/issue-repository";
    11	import * as orgRepo from "@/server/repositories/organization-repository";
    12	import * as searchRepo from "@/server/repositories/search-repository";
    13	import * as usageRepo from "@/server/repositories/usage-repository";
    14	import { toIsoTimestamp } from "@/types/common";
    15	import { runJob } from "./types";
    16	import type { JobResult } from "@/server/jobs/types";
    17	
    18	const ORG_BATCH = 25;
    19	const PAGE_SIZE = 100;
    20	const MS_PER_DAY = 24 * 60 * 60 * 1000;
    21	
    22	const logger = createLogger("cleanup-archived-job");
    23	
    24	/**
    25	 * The retention sweep. Soft-deleted rows are kept for as long as the plan
    26	 * promises and no longer: the cut-off comes from `retentionDays`, so an
    27	 * enterprise tenant keeps years of history where a free one keeps a month.
    28	 *
    29	 * Only the search documents are actually dropped here — the issue rows stay,
    30	 * because the audit log still points at them — while the audit rows past the
    31	 * window are purged outright.
    32	 */
    33	export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
    34	  return runJob("cleanup-archived", async (result) => {
    35	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
    36	
    37	    for (const orgId of orgIds) {
    38	      const org = await orgRepo.findOrgById(orgId);
    39	      if (!org) continue;
    40	
    41	      const { retentionDays } = getPlanLimits(org.plan);
    42	      const cutoff = toIsoTimestamp(
    43	        new Date(now.getTime() - retentionDays * MS_PER_DAY),
    44	      );
    45	
    46	      const archived = await issueRepo.listIssues({
    47	        orgId,
    48	        limit: PAGE_SIZE,
    49	        cursor: null,
    50	        includeArchived: true,
    51	      });
    52	
    53	      for (const issue of archived.items) {
    54	        if (!isArchived(issue)) continue;
    55	        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;
    56	
    57	        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
    58	        result.processed += 1;
    59	      }
    60	
    61	      try {
    62	        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
    63	        result.processed += purged;
    64	      } catch (error) {
    65	        result.failed += 1;
    66	        logger.error("activity purge failed", {
    67	          orgId,
    68	          reason: error instanceof Error ? error.message : String(error),
    69	        });
    70	      }
    71	    }
    72	  });
    73	}

