export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}

/** How long an archive stays restorable: the plan's `retentionDays`, in ms. */
export function retentionWindowMs(retentionDays: number): number {
  return retentionDays * MS_PER_DAY;
}

/**
 * The instant before which an archive has used up its retention window. A row
 * archived at or before this cut-off is expired.
 */
export function retentionCutoff(now: Date, retentionDays: number): IsoTimestamp {
  return toIsoTimestamp(
    new Date(now.getTime() - retentionWindowMs(retentionDays)),
  );
}

/** True once `retentionDays × 24h` has passed since `archivedAt`. */
export function isRetentionExpired(
  archivedAt: IsoTimestamp,
  retentionDays: number,
  now: Date = new Date(),
): boolean {
  return (
    now.getTime() - Date.parse(archivedAt) >= retentionWindowMs(retentionDays)
  );
}

export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

/** A restore the domain refuses; `reason` says which gate turned it away. */
export class RestoreRefusedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
    readonly reason: RestoreRefusalReason,
  ) {
    super(`${entity} ${id} cannot be restored (${reason}).`);
    this.name = "RestoreRefusedError";
  }
}

