/**
 * Archived issues whose retention window closed at or before `cutoff`, in id
 * order, one page after `afterId`. The sweep walks by id rather than re-reading
 * the head of the list, so a page it could not purge never stalls the walk.
 */
export async function listExpiredIssues(input: {
  orgId: OrgId;
  cutoff: IsoTimestamp;
  afterId: IssueId | null;
  limit: number;
}): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, input.orgId),
          lte(issues.archivedAt, input.cutoff),
          input.afterId === null ? undefined : gt(issues.id, input.afterId),
        ),
      ),
    )
    .orderBy(issues.id)
    .limit(input.limit)
    .all();

  return rows.map((row) => toIssue(row));
}

const BYTES_PER_MB = 1024 * 1024;

/**
 * Deletes an archived issue for good, with its label links, comments,
 * attachments and search documents, in one transaction. The project's number
 * counter is raised to this issue's number first, so the number is never handed
 * out again. Returns the storage the attachments were counted for: each one
 * rounded up to whole megabytes, as on upload.
 */
export async function purgeIssue(
  orgId: OrgId,
  issue: Issue,
): Promise<{ storageMb: number }> {
  return getDb().transaction((tx) => {
    const commentIds = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issue.id)),
      )
      .all()
      .map((row) => row.id);

    const attachmentRows = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issue.id),
        ),
      )
      .all();

    const counter = tx
      .select({ value: issueNumberCounters.lastNumber })
      .from(issueNumberCounters)
      .where(
        and(
          orgPredicate(issueNumberCounters.orgId, orgId),
          eq(issueNumberCounters.projectId, issue.projectId),
        ),
      )
      .get();
    const lastNumber = Math.max(counter?.value ?? 0, issue.number);
    tx.insert(issueNumberCounters)
      .values({ projectId: issue.projectId, orgId, lastNumber })
      .onConflictDoUpdate({
        target: issueNumberCounters.projectId,
        set: { lastNumber },
      })
      .run();

    tx.delete(searchIndex)
      .where(
        and(
          orgPredicate(searchIndex.orgId, orgId),
          or(
            and(
              eq(searchIndex.subjectKind, "issue"),
              eq(searchIndex.subjectId, issue.id),
            ),
            commentIds.length === 0
              ? undefined
              : and(
                  eq(searchIndex.subjectKind, "comment"),
                  inArray(searchIndex.subjectId, commentIds),
                ),
          ),
        ),
      )
      .run();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, issue.id),
        ),
      )
      .run();
    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issue.id),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issue.id)),
      )
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issue.id)))
      .run();

    return {
      storageMb: attachmentRows.reduce(
        (total, row) => total + Math.ceil(row.sizeBytes / BYTES_PER_MB),
        0,
      ),
    };
  });
}

