/**
 * Restoring archived issues and the retention sweep that purges them.
 *
 * An archived issue is restorable while the plan's `retentionDays` window is
 * open. Once it has closed the issue is expired: restore refuses it, and the
 * sweep deletes it with its comments, attachments and search documents. The
 * purged number is never handed out again.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { getDb, activityEvents, issues } from "@/server/db";
import { RestoreRefusedError } from "@/lib/soft-delete";
import { NotFoundError } from "@/server/services/_support";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import { and, eq } from "drizzle-orm";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { IssueId, OrgId, ProjectId } from "@/types/common";

const MB = 1024 * 1024;
const LONG_AGO = "2020-01-01T00:00:00.000Z";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("restore");
  registerEventHandlers();
  await usageRepo.recomputeUsage(tenant.org.id);
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

/** Moves an archived issue's `archived_at` into the past, past the window. */
function backdateArchive(orgId: OrgId, issueId: IssueId, when: string): void {
  getDb()
    .update(issues)
    .set({ archivedAt: when })
    .where(and(eq(issues.orgId, orgId), eq(issues.id, issueId)))
    .run();
}

async function createIssue(title: string, projectId = tenant.project.id) {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title }),
  );
}

async function refusedReason(promise: Promise<unknown>): Promise<string> {
  try {
    await promise;
  } catch (error) {
    expect(error).toBeInstanceOf(RestoreRefusedError);
    return (error as RestoreRefusedError).reason;
  }
  throw new Error("expected the restore to be refused");
}

describe("restoring an archived issue", () => {
  it("brings the issue back under its original number and re-counts it", async () => {
    const issue = await createIssue("Come back later");
    const before = await usageRepo.getUsage(tenant.org.id);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const restored = await issueService.restoreIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    expect(restored.archivedAt).toBeNull();
    expect(restored.number).toBe(issue.number);
    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.issuesUsed).toBe(before.issuesUsed);
  });

  it("makes the issue searchable again and records it in the audit log", async () => {
    const issue = await createIssue("Searchable comeback");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    await issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id);

    const hits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "Searchable comeback",
      kinds: ["issue"],
      projectId: undefined,
      limit: 10,
      cursor: null,
    });
    expect(hits.items.map((row) => row.subjectId)).toContain(issue.id);

    const logged = getDb()
      .select()
      .from(activityEvents)
      .where(
        and(
          eq(activityEvents.orgId, tenant.org.id),
          eq(activityEvents.action, "issue.restored"),
          eq(activityEvents.subjectId, issue.id),
        ),
      )
      .all();
    expect(logged).toHaveLength(1);
  });

  it("refuses an issue that is not archived, changing nothing", async () => {
    const issue = await createIssue("Never archived");

    await expect(
      refusedReason(
        issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
      ),
    ).resolves.toBe("not_archived");
  });

  it("refuses an archive whose retention window has closed", async () => {
    const issue = await createIssue("Too old to restore");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    backdateArchive(tenant.org.id, issue.id, LONG_AGO);

    await expect(
      refusedReason(
        issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
      ),
    ).resolves.toBe("expired");

    const stillArchived = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stillArchived?.archivedAt).not.toBeNull();
  });

  it("refuses an issue whose project is archived", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Restore scratch",
      slug: "restore-scratch",
      key: "RSC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const issue = await createIssue("Stranded", scratch.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: scratch.id,
      archiveIssues: true,
    });

    await expect(
      refusedReason(
        issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
      ),
    ).resolves.toBe("project_archived");
  });

  it("requires the archive permission, with the author's ownership escalation", async () => {
    const issue = await createIssue("Viewer may not touch");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await expect(
      issueService.restoreIssue(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toThrow();

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).resolves.toMatchObject({ archivedAt: null });
  });
});

describe("the retention sweep purging expired issues", () => {
  it("deletes the issue with its comments, attachments and search documents, and refunds storage", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Purge scratch",
      slug: "purge-scratch",
      key: "PRG",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const keep = await createIssue("Keeper", scratch.id);
    const doomed = await createIssue("Doomed with extras", scratch.id);

    const comment = await commentRepo.insertComment(
      {
        orgId: tenant.org.id,
        issueId: doomed.id,
        body: "a comment that goes too",
        parentId: null,
        mentionedUserIds: [],
      },
      tenant.userIds.member,
    );
    await searchService.indexComment(tenant.org.id, comment);

    await attachmentService.addAttachment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doomed.id,
      filename: "spec.pdf",
      contentType: "application/pdf",
      sizeBytes: Math.round(1.5 * MB),
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, doomed.id);
    backdateArchive(tenant.org.id, doomed.id, LONG_AGO);

    const storageBefore = (await usageRepo.getUsage(tenant.org.id)).storageMbUsed;
    const issuesBefore = (await usageRepo.getUsage(tenant.org.id)).issuesUsed;

    const result = await runCleanupArchivedJob(new Date());
    expect(result.failed).toBe(0);

    expect(await issueRepo.findIssueById(tenant.org.id, doomed.id)).toBeNull();
    expect(
      await commentRepo.findCommentById(tenant.org.id, comment.id),
    ).toBeNull();
    expect(
      await attachmentRepo.listAttachments(tenant.org.id, doomed.id),
    ).toEqual([]);

    const docs = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "comment that goes too",
      kinds: ["comment"],
      projectId: undefined,
      limit: 10,
      cursor: null,
    });
    expect(docs.items).toEqual([]);

    const usageAfter = await usageRepo.getUsage(tenant.org.id);
    expect(usageAfter.storageMbUsed).toBe(storageBefore - 2);
    expect(usageAfter.issuesUsed).toBe(issuesBefore);

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, doomed.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(await issueRepo.findIssueById(tenant.org.id, keep.id)).not.toBeNull();
  });

  it("never reuses the number of a purged issue", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Numbering scratch",
      slug: "numbering-scratch",
      key: "NUM",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const first = await createIssue("First", scratch.id);
    const last = await createIssue("Last and purged", scratch.id);
    expect(last.number).toBe(first.number + 1);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, last.id);
    backdateArchive(tenant.org.id, last.id, LONG_AGO);
    await runCleanupArchivedJob(new Date());

    const next = await createIssue("After the purge", scratch.id);
    expect(next.number).toBe(last.number + 1);
    expect(
      await issueRepo.nextIssueNumber(tenant.org.id, scratch.id as ProjectId),
    ).toBe(next.number + 1);
  });
});
